// In utils/todoFilters.ts
export const filterTodos = (todos: Todo[], filter: FilterType): Todo[] => {
  const filters: Record<FilterType, (t: Todo) => boolean> = {
    active: t => !t.completed,
    completed: t => t.completed,
    all: () => true
  };
  return todos.filter(filters[filter]);
};

